+	cell_add_fast (area, cover, cx - x_org, 0, fy_prev, HB_RASTER_ONE_PIXEL, fy_b, wind, x_min, x_max);
 	fy_prev = fy_b;
       }

-      cell_add (area, cover, width, cx1 - x_org, 0, fy_prev, fx1, fy1, wind, x_min, x_max);
+      cell_add_fast (area, cover, cx1 - x_org, 0, fy_prev, fx1, fy1, wind, x_min, x_max);
       return;
     }

